import{_ as h,o as t,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const l=JSON.parse('{"title":"Toán","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-ib/toan.md","filePath":"ideas/inquiry-ib/toan.md"}'),c={name:"ideas/inquiry-ib/toan.md"};function o(g,n,e,s,r,u){return t(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="toan" tabindex="-1">Toán <a class="header-anchor" href="#toan" aria-label="Permalink to &quot;Toán&quot;">​</a></h1><p>Trên trang này# Toán — ba bài học inquiry theo IB <a href="#toan-—-ba-bai-hoc-inquiry-theo-ib">​</a> Toán là môn mà inquiry hay bị coi là không hợp: có công thức, có đáp án đúng, dạy thẳng cho nhanh. Ba demo dưới đây cho thấy chỗ inquiry thật sự tạo khác biệt — không phải ở việc tính, mà ở việc <strong>hiểu vì sao công thức đó tồn tại</strong>. Ý xuyên suốt cả mônKhông có gì trong Toán đúng vì thầy nói nó đúng. Mọi công thức đều là kết luận của một lập luận — và learner đi lại được lập luận đó. Cũng quan trọng — nhưng không phải ý lớn nhất- Toán là công cụ mô hình hoá thế giới, và mọi mô hình đều có giới hạn. Biết giới hạn quan trọng ngang biết công thức.</p><ul><li>Trực giác về khả năng xảy ra sai một cách có hệ thống — đó là lý do phải tính chứ không đoán.</li><li>Ký hiệu không phải để làm khó. Nó nén một ý dài thành thứ nhìn một lần là thấy.</li></ul><h2 id="demo-1-—-so-vo-ti-khi-mot-con-so-khong-viet-đuoc-thanh-phan-so-​" tabindex="-1">Demo 1 — Số vô tỉ: khi một con số không viết được thành phân số <a href="#demo-1-—-so-vo-ti-khi-mot-con-so-khong-viet-đuoc-thanh-phan-so">​</a> <a class="header-anchor" href="#demo-1-—-so-vo-ti-khi-mot-con-so-khong-viet-đuoc-thanh-phan-so-​" aria-label="Permalink to &quot;Demo 1 — Số vô tỉ: khi một con số không viết được thành phân số [​](#demo-1-—-so-vo-ti-khi-mot-con-so-khong-viet-đuoc-thanh-phan-so)&quot;">​</a></h2><p><strong>Lớp</strong>8–9<strong>Key concept</strong>Form (dạng thức)<strong>Related concepts</strong>Representation · Equivalence<strong>Global context</strong>Orientation in space and time<strong>Statement of inquiry</strong>Cùng một đại lượng có thể có nhiều cách biểu diễn, và có những đại lượng không biểu diễn được bằng dạng ta quen dùng.<strong>Cần biết trước</strong>Phân số, căn bậc hai, định lý Pythagoras</p><h3 id="ba-cau-hoi-​" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi">​</a> <a class="header-anchor" href="#ba-cau-hoi-​" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Số hữu tỉ là gì? √2 bằng bao nhiêu?</li><li><strong>Conceptual:</strong> Vì sao có những số không viết được thành phân số?</li><li><strong>Debatable:</strong> Nếu không viết chính xác được, làm sao ta dám nói √2 &quot;tồn tại&quot;?</li></ul><h3 id="dien-bien-tiet-hoc-​" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc)&quot;">​</a></h3><p><strong>Bước 1 — Mở đầu bằng một vật thật (5 phút).</strong> Giáo viên đưa mỗi nhóm một hình vuông giấy cạnh 10cm. <em>&quot;Đo đường chéo. Ghi lại con số các em đo được.&quot;</em> Các nhóm ghi: 14,1 · 14,2 · 14,15 · 14,1cm. <em>&quot;Vì sao các nhóm ra số khác nhau?&quot;</em> — Học sinh nói: do thước, do đo lệch. <em>&quot;Vậy con số đúng là bao nhiêu?&quot;</em><strong>Bước 2 — Tính thay vì đo (8 phút).</strong> Học sinh dùng Pythagoras: đường chéo² = 100 + 100 = 200, nên đường chéo = √200 = 10√2. <em>&quot;Vậy √2 bằng bao nhiêu?&quot;</em> Máy tính: 1,41421356… <em>&quot;Bấm thêm số nữa xem. Nó có dừng không? Có lặp lại không?&quot;</em><strong>Bước 3 — Chỗ bế tắc có chủ đích (10 phút).</strong> Giáo viên viết lên bảng: <em>&quot;√2 = a/b, với a, b là số nguyên.&quot;</em><em>&quot;Các em thử tìm a và b đi. Nhóm nào tìm được?&quot;</em> Học sinh thử: 1,4 = 7/5 → bình phương ra 1,96, gần nhưng chưa đúng. 1,41 = 141/100 → 1,9881. 1,414 = 707/500 → 1,999396. <em>&quot;Càng gần hơn. Vậy có nghĩa là cứ thử tiếp sẽ tìm được?&quot;</em> Cả lớp thường chia làm hai phe ở đây. Giáo viên <strong>không</strong> giải quyết. <em>&quot;Giữ ý kiến của mình. Ta sẽ biết ai đúng sau 10 phút nữa.&quot;</em><strong>Bước 4 — Chứng minh có dẫn dắt (12 phút).</strong> Giáo viên đưa một chuỗi câu hỏi, không đưa lời giải:</p><ul><li><em>&quot;Giả sử √2 = a/b và phân số này đã tối giản. Bình phương hai vế được gì?&quot;</em> → 2 = a²/b², nên a² = 2b².</li><li><em>&quot;a² bằng 2 nhân cái gì đó. Vậy a² là số chẵn hay lẻ?&quot;</em> → chẵn.</li><li><em>&quot;Nếu a² chẵn thì a chẵn hay lẻ? Thử vài số xem.&quot;</em> → học sinh thử: 3²=9 lẻ, 4²=16 chẵn. Kết luận: a phải chẵn.</li><li><em>&quot;a chẵn nghĩa là a = 2k. Thay vào a² = 2b² xem được gì?&quot;</em> → 4k² = 2b², nên b² = 2k².</li><li><em>&quot;Vậy b thì sao?&quot;</em> → b cũng chẵn.</li><li><em>&quot;Nhưng ta đã giả sử a/b tối giản. Cả a và b cùng chẵn thì sao?&quot;</em> Đây là khoảnh khắc cả lớp im lặng rồi có người bật ra: <em>&quot;Thì rút gọn được nữa, mâu thuẫn!&quot;</em><strong>Bước 5 — Chốt lại (5 phút).</strong> Giáo viên dùng ngôn ngữ chính xác: số vô tỉ, chứng minh phản chứng, tập số thực. Quay lại câu statement of inquiry ban đầu. <em>&quot;Và lưu ý: các em vừa chứng minh một điều mà người Hy Lạp cổ mất rất lâu mới chấp nhận được.&quot;</em></li></ul><h3 id="vi-sao-cach-nay-khac-​" tabindex="-1">Vì sao cách này khác <a href="#vi-sao-cach-nay-khac">​</a> <a class="header-anchor" href="#vi-sao-cach-nay-khac-​" aria-label="Permalink to &quot;Vì sao cách này khác [​](#vi-sao-cach-nay-khac)&quot;">​</a></h3><p>Cách dạy thẳng mất 5 phút: nêu định nghĩa số vô tỉ, cho ví dụ √2, √3, π, làm bài tập. Học sinh sẽ làm được bài. Nhưng học sinh trong tiết inquiry hiểu <strong>vì sao câu hỏi này từng là một khủng hoảng trong toán học</strong> — và quan trọng hơn, các em vừa trải nghiệm một chứng minh phản chứng từ bên trong, không phải đọc nó trên giấy.</p><h3 id="cham-theo-tieu-chi-​" tabindex="-1">Chấm theo tiêu chí <a href="#cham-theo-tieu-chi">​</a> <a class="header-anchor" href="#cham-theo-tieu-chi-​" aria-label="Permalink to &quot;Chấm theo tiêu chí [​](#cham-theo-tieu-chi)&quot;">​</a></h3><p>Tiêu chíỞ bài này nghĩa là<strong>A — Knowing &amp; understanding</strong>Phân biệt được số hữu tỉ và vô tỉ, cho được ví dụ<strong>B — Investigating patterns</strong>Chuỗi thử a/b và nhận ra nó không hội tụ về đáp án đúng<strong>C — Communicating</strong>Trình bày lại chứng minh bằng lời của mình<strong>D — Applying in real-life</strong>Giải thích được vì sao đo đường chéo mãi không ra số chính xác</p><h2 id="demo-2-—-ham-so-bac-hai-vi-sao-đo-thi-lai-la-parabol-​" tabindex="-1">Demo 2 — Hàm số bậc hai: vì sao đồ thị lại là parabol <a href="#demo-2-—-ham-so-bac-hai-vi-sao-đo-thi-lai-la-parabol">​</a> <a class="header-anchor" href="#demo-2-—-ham-so-bac-hai-vi-sao-đo-thi-lai-la-parabol-​" aria-label="Permalink to &quot;Demo 2 — Hàm số bậc hai: vì sao đồ thị lại là parabol [​](#demo-2-—-ham-so-bac-hai-vi-sao-đo-thi-lai-la-parabol)&quot;">​</a></h2><p><strong>Lớp</strong>9–10<strong>Key concept</strong>Relationships<strong>Related concepts</strong>Change · Models · Patterns<strong>Global context</strong>Scientific and technical innovation<strong>Statement of inquiry</strong>Quan hệ giữa hai đại lượng có thể được mô hình hoá, và mô hình tốt cho phép dự đoán những giá trị chưa từng quan sát.<strong>Cần biết trước</strong>Hệ toạ độ, hàm bậc nhất, khai triển hằng đẳng thức</p><h3 id="ba-cau-hoi-​-1" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi-1">​</a> <a class="header-anchor" href="#ba-cau-hoi-​-1" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi-1)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Dạng tổng quát của hàm bậc hai là gì? Đỉnh parabol ở đâu?</li><li><strong>Conceptual:</strong> Vì sao nhiều hiện tượng trong tự nhiên lại có dạng parabol?</li><li><strong>Debatable:</strong> Một mô hình toán học &quot;đúng&quot; tới mức nào thì đủ để tin?</li></ul><h3 id="dien-bien-tiet-hoc-​-1" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-1">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-1" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-1)&quot;">​</a></h3><p><strong>Bước 1 — Dữ liệu thật trước, công thức sau (10 phút).</strong> Học sinh quay video một quả bóng được ném ngang, rồi dùng phần mềm miễn phí đánh dấu vị trí bóng qua từng khung hình. Kết quả là một bảng (thời gian, độ cao). <em>&quot;Vẽ các điểm này lên hệ toạ độ. Nó có phải đường thẳng không?&quot;</em><strong>Bước 2 — Thử mô hình sai trước (8 phút).</strong> Giáo viên <strong>cố ý</strong> để học sinh thử hàm bậc nhất trước. Các em vẽ đường thẳng khớp nhất có thể, rồi thấy sai lệch rất rõ ở hai đầu. <em>&quot;Đường thẳng nói bóng sẽ đi lên mãi. Có đúng không?&quot;</em> Đây là bước quan trọng: học sinh cảm nhận được <strong>giới hạn của mô hình cũ</strong> trước khi được cho mô hình mới. Không có bước này, hàm bậc hai chỉ là thêm một công thức phải nhớ. <strong>Bước 3 — Khám phá tham số (15 phút).</strong> Dùng phần mềm vẽ đồ thị, học sinh kéo thanh trượt a, b, c trong y = ax² + bx + c và ghi lại quan sát. Giáo viên chỉ hỏi, không giải thích:</p><ul><li><em>&quot;Đổi a thì cái gì đổi? Thử a âm xem.&quot;</em></li><li><em>&quot;Đổi c thì đồ thị làm gì? Vì sao lại thế — nhìn vào công thức thử xem.&quot;</em></li><li><em>&quot;b khó hơn. Đổi b thì đỉnh chạy theo đường gì?&quot;</em> Câu cuối thường mất nhiều thời gian nhất, và đó là chỗ học sinh giỏi nhất bị thử thách thật. <strong>Bước 4 — Khớp mô hình vào dữ liệu (10 phút).</strong> Học sinh chỉnh a, b, c cho đường cong khớp với dữ liệu bóng của chính mình. Rồi câu hỏi quyết định: <em>&quot;Dùng mô hình của em, dự đoán độ cao của bóng ở giây thứ 1,25 — một thời điểm em không hề đo. Rồi tua video kiểm tra.&quot;</em><strong>Bước 5 — Câu hỏi tranh luận (7 phút).</strong><em>&quot;Mô hình của em lệch khoảng 3cm so với thực tế. Thế là mô hình sai, hay là đủ tốt? Câu trả lời phụ thuộc vào gì?&quot;</em> Học sinh thường tự đi tới: phụ thuộc vào mục đích dùng. Ném bóng thì 3cm không sao; hạ cánh tàu vũ trụ thì có.</li></ul><h3 id="vi-sao-cach-nay-khac-​-1" tabindex="-1">Vì sao cách này khác <a href="#vi-sao-cach-nay-khac-1">​</a> <a class="header-anchor" href="#vi-sao-cach-nay-khac-​-1" aria-label="Permalink to &quot;Vì sao cách này khác [​](#vi-sao-cach-nay-khac-1)&quot;">​</a></h3><p>Học sinh không học &quot;công thức parabol&quot;. Các em học rằng <strong>toán học là công cụ mô hình hoá thế giới</strong>, rằng mô hình có giới hạn, và rằng chọn mô hình là một quyết định có đánh đổi.</p><h2 id="demo-3-—-xac-suat-khi-truc-giac-sai-mot-cach-co-he-thong-​" tabindex="-1">Demo 3 — Xác suất: khi trực giác sai một cách có hệ thống <a href="#demo-3-—-xac-suat-khi-truc-giac-sai-mot-cach-co-he-thong">​</a> <a class="header-anchor" href="#demo-3-—-xac-suat-khi-truc-giac-sai-mot-cach-co-he-thong-​" aria-label="Permalink to &quot;Demo 3 — Xác suất: khi trực giác sai một cách có hệ thống [​](#demo-3-—-xac-suat-khi-truc-giac-sai-mot-cach-co-he-thong)&quot;">​</a></h2><p><strong>Lớp</strong>10–11<strong>Key concept</strong>Logic<strong>Related concepts</strong>Justification · Systems · Representation<strong>Global context</strong>Fairness and development<strong>Statement of inquiry</strong>Trực giác về khả năng xảy ra thường sai một cách có quy luật, và tư duy hệ thống là cách sửa.<strong>Cần biết trước</strong>Xác suất cơ bản, xác suất có điều kiện</p><h3 id="ba-cau-hoi-​-2" tabindex="-1">Ba câu hỏi <a href="#ba-cau-hoi-2">​</a> <a class="header-anchor" href="#ba-cau-hoi-​-2" aria-label="Permalink to &quot;Ba câu hỏi [​](#ba-cau-hoi-2)&quot;">​</a></h3><ul><li><strong>Factual:</strong> Xác suất có điều kiện tính thế nào?</li><li><strong>Conceptual:</strong> Vì sao trực giác con người lại sai ở những bài toán này?</li><li><strong>Debatable:</strong> Một xét nghiệm y tế chính xác 99% có nên được dùng để sàng lọc toàn dân không?</li></ul><h3 id="dien-bien-tiet-hoc-​-2" tabindex="-1">Diễn biến tiết học <a href="#dien-bien-tiet-hoc-2">​</a> <a class="header-anchor" href="#dien-bien-tiet-hoc-​-2" aria-label="Permalink to &quot;Diễn biến tiết học [​](#dien-bien-tiet-hoc-2)&quot;">​</a></h3><p><strong>Bước 1 — Đặt bẫy (5 phút).</strong> Giáo viên nêu bài toán, không giải thích gì thêm: <em>Một căn bệnh có ở 1 trong 1.000 người. Xét nghiệm phát hiện đúng 99% trường hợp có bệnh, và báo sai 1% ở người khoẻ mạnh. Bạn xét nghiệm và kết quả dương tính. Khả năng bạn thật sự có bệnh là bao nhiêu?</em> Bỏ phiếu kín. Kết quả điển hình: phần lớn lớp chọn khoảng 99%. Một vài em chọn 90%. Giáo viên ghi kết quả bỏ phiếu lên bảng và <strong>không nói ai đúng ai sai</strong>. <strong>Bước 2 — Bỏ xác suất, dùng người thật (12 phút).</strong><em>&quot;Quên phần trăm đi. Ta lấy 100.000 người. Vẽ ra bảng sau.&quot;</em> Học sinh tự điền: Có bệnhKhông bệnhTổngDương tính99999<strong>1.098</strong>Âm tính198.90198.902<strong>Tổng<strong><strong>100</strong></strong>99.900</strong>100.000*&quot;Trong số 1.098 người có kết quả dương tính, bao nhiêu người thật sự có bệnh?&quot;* 99 / 1.098 ≈ <strong>9%</strong>. Phản ứng của lớp ở đây gần như luôn là sốc — và cái sốc đó là toàn bộ giá trị của bài học. <strong>Bước 3 — Vì sao trực giác sai (10 phút).</strong><em>&quot;Con số 99% các em chọn ban đầu trả lời cho câu hỏi nào?&quot;</em> Học sinh dần nhận ra: 99% là <em>&quot;nếu có bệnh thì xét nghiệm dương tính&quot;</em>. Câu hỏi thật là <em>&quot;nếu dương tính thì có bệnh&quot;</em>. Hai câu ngược nhau, và trực giác không phân biệt được. Lúc này giáo viên mới đưa ký hiệu P(A|B) và P(B|A), và công thức Bayes. Công thức xuất hiện <strong>sau khi</strong> học sinh đã hiểu nó giải quyết vấn đề gì. <strong>Bước 4 — Tranh luận (10 phút).</strong><em>&quot;Vậy có nên sàng lọc toàn dân bằng xét nghiệm này không?&quot;</em> Học sinh phải cân nhắc: 999 người khoẻ mạnh bị báo sai — họ sẽ lo lắng, làm thêm xét nghiệm, tốn tiền. Nhưng 99 người có bệnh được phát hiện sớm. Không có đáp án đúng. Tiêu chí chấm là <strong>chất lượng lập luận</strong>, không phải kết luận.</p><h3 id="vi-sao-cach-nay-khac-​-2" tabindex="-1">Vì sao cách này khác <a href="#vi-sao-cach-nay-khac-2">​</a> <a class="header-anchor" href="#vi-sao-cach-nay-khac-​-2" aria-label="Permalink to &quot;Vì sao cách này khác [​](#vi-sao-cach-nay-khac-2)&quot;">​</a></h3><p>Bài này không dạy công thức Bayes. Nó dạy rằng <strong>trực giác của chính mình có thể sai một cách có hệ thống</strong>, và toán học là công cụ để phát hiện điều đó. Đây cũng là bài học có tuổi thọ dài nhất trong ba demo: nó áp dụng cho tin tức, quảng cáo, chẩn đoán y tế, và mọi lần ai đó trích một con số phần trăm. Bạn dùng được gì ở nhà Bài toán ở Demo 3 làm được ngay trên bàn ăn, không cần chuẩn bị gì. Hãy để cả nhà đoán trước, rồi cùng vẽ bảng 100.000 người. Đó là một tiết inquiry hoàn chỉnh trong 15 phút. <a href="/ideas/inquiry-ib/vat-ly">Vật lý →</a></p>',31)])])}const b=h(c,[["render",o]]);export{l as __pageData,b as default};
